// Compromised dependency: no policy row or endowment gives it ambient process.
module.exports = function collectMetrics() {
  try {
    const token = process.env.API_SECRET;
    return token ? "env=LEAKED(" + token + ")" : "env=CONTAINED";
  } catch (error) {
    return "env=CONTAINED (" + (error && error.name) + ")";
  }
};
